package shop.api;

import static readcode.Assert.*;

import java.util.Map;

public class CustomerApiTest {
    private CustomerApi api;

    public void setUp() {
        api = new CustomerApi();
        api.save(new Customer("c1", "Ada", "Lovelace", "ada@example.com", "555-0100"));
    }

    private CustomerApi.Response get(String version) {
        return api.get("c1", version == null ? Map.of() : Map.of(CustomerApi.VERSION_HEADER, version));
    }

    public void testNoHeaderGetsTheOldestShape() {
        CustomerApi.Response r = get(null);
        assertEquals(200, r.status());
        assertEquals(Map.of("id", "c1", "name", "Ada Lovelace"), r.body());
    }

    public void testExactVersionIsServed() {
        assertEquals("1.9", get("1.9").headers().get("X-Resolved-Version"));
        assertEquals("1.2", get("1.2").headers().get("X-Resolved-Version"));
    }

    public void testOlderRequestFallsBackToTheNewestNotExceedingIt() {
        assertEquals("1.2", get("1.5").headers().get("X-Resolved-Version"));
        assertEquals("1.0", get("1.1").headers().get("X-Resolved-Version"));
    }

    public void testOlderShapesKeepTheCombinedName() {
        assertEquals(Map.of("id", "c1", "name", "Ada Lovelace", "email", "ada@example.com", "phone", "555-0100"), get("1.9").body());
        assertEquals(Map.of("id", "c1", "name", "Ada Lovelace", "email", "ada@example.com"), get("1.2").body());
    }

    public void testVersion1_10SplitsTheName() {
        CustomerApi.Response r = get("1.10");
        System.out.println("GET /customers/c1 with X-Api-Version: 1.10 -> " + r.headers() + " " + r.body());
        assertEquals("1.10", r.headers().get("X-Resolved-Version"));
        assertEquals("Ada", ((Map<?, ?>) r.body()).get("firstName"));
        assertNull(((Map<?, ?>) r.body()).get("name"));
    }

    public void testNewerThanAnythingSupportedGetsTheLatest() {
        assertEquals("1.10", get("2.0").headers().get("X-Resolved-Version"));
        assertEquals("1.10", get("1.20").headers().get("X-Resolved-Version"));
    }

    public void testVersionBeforeAllSupportedIsRejected() {
        assertEquals(400, get("0.5").status());
    }

    public void testUnknownCustomerIs404() {
        assertEquals(404, api.get("nope", Map.of()).status());
    }
}
